 live=detail(main)['row'];api('/api/cross-records/'+str(main),{'action':'publish','revision':live['revision']},method='PATCH');page.evaluate("window.dispatchEvent(new Event('orbit-cross-management'))");expect(row.locator('.product-current-flow')).to_contain_text('发布人：测试主账号');expect(row.locator('.product-current-flow')).to_contain_text('视频子包制作人：新负责人');assert scalar('SELECT status FROM cross_records WHERE id=?',(video,))=='rejected';page.screenshot(path=str(out/'product-current-flow.png'));checks+=3
 nav.get_by_role('button',name='项目工作台',exact=True).click();page.get_by_role('tab',name='母版制作',exact=False).click();panel=page.locator('.task-workbench-list:visible');taskrow=panel.locator('tr[data-task-id="'+str(mother_task['id'])+'"]');expect(taskrow).to_contain_text('新负责人');taskrow.scroll_into_view_if_needed();cells=taskrow.locator('td');assert cells.count()==7;assert cells.nth(0).bounding_box()['width']<=60;assert cells.nth(1).bounding_box()['width']>=210;assert cells.nth(5).bounding_box()['width']>=120;button=cells.nth(6).get_by_role('button',name='查看资料',exact=True);assert button.bounding_box()['height']<45;assert cells.nth(5).locator('.task-state').evaluate('(e)=>getComputedStyle(e).whiteSpace')=='nowrap';checks+=6;page.screenshot(path=str(out/'workbench-wide.png'))
